css:
@font-face{font-family:'Inter';font-style:normal;font-weight:400 800;font-display:swap;src:url('https://fonts.gstatic.com/s/inter/v18/UcCO3FwrK3iLTeHuS_fvQtMwCp50KnMa2JL7SUc.woff2') format('woff2');}
:root{
  --font-sans:'Inter',Arial,Helvetica,sans-serif;
  --brand:#da251c; --brand-dark:#a81c15;
  --ink:#1a1a1a; --ink-2:#4a4a4a; --ink-3:#767676;
  --line:#dcdcdc; --line-strong:#b8b8b8;
  --sunken:#f6f6f6; --tint:#fdf1f0; --ok:#1f7a3f; --white:#ffffff;
}
.rtr-wrap { font-family: var(--font-sans); font-size: 7.5pt; color: var(--ink); -webkit-print-color-adjust: exact; print-color-adjust: exact; }

/* header lockup: logo left, title right, brand rule under */
.rtr-header { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-bottom: 2px solid var(--brand); padding-bottom: 6px; margin-bottom: 10px; }
#rtr-logo { width: 258px; height: 74px; display: block; }
.rtr-title { margin: 0; text-align: right; font-size: 15pt; font-weight: 700; letter-spacing: .04em; text-transform: uppercase; color: var(--brand); line-height: 1.1; }

.rtr-table { width: 100%; border-collapse: collapse; table-layout: auto; border: 1.5px solid var(--line-strong); }
.rtr-table th, .rtr-table td { border: 1px solid var(--line); padding: 4px 6px; vertical-align: middle; font-size: 7.5pt; -webkit-print-color-adjust: exact; print-color-adjust: exact; }

/* secondary header rows (item code / description / batch) */
.rtr-table thead tr th, .rtr-table thead tr td { background: var(--sunken); }
.lbl { font-weight: 600; color: var(--brand-dark); }

/* primary column header (Check On / Test / Requirement / qty) */
.rtr-head-row th { background: var(--brand); color: var(--white); font-weight: 600; border-color: var(--brand-dark); letter-spacing: .02em; }

/* meta box */
.rtr-table .meta-box { border: 1px solid var(--line-strong) !important; background: var(--white) !important; vertical-align: top; padding: 8px; }
.meta-box div { border: none; margin-bottom: 4px; color: var(--ink-2); }
.meta-box div b { color: var(--ink); font-weight: 600; }

.rotate-cell { width: 60px; min-width: 50px; }
.rotate-text { writing-mode: vertical-rl; transform: rotate(180deg); white-space: nowrap; display: block; min-height: 65px; text-align: left; }

.col-group { font-weight: 600; vertical-align: middle; width: 140px; background: var(--sunken); color: var(--ink); }
.col-test { width: 120px; color: var(--ink); }
.col-req { width: 140px; color: var(--ink-2); }
.col-val { text-align: center; width: 65px; color: var(--ink-2); }
.col-val.is-ok { color: var(--ok); font-weight: 600; }

/* group separator */
.group-start td { border-top: 1.5px solid var(--line-strong); }

#rtr-footer { display: block; width: 100%; max-width: 100%; height: auto; margin-top: 10px; }
